algorithms.pseudocode:
function SATURATE(seeds, rules, max_iter, max_size):
    E <- new EGraph
    terms <- seeds
    for i = 1 to max_iter:
        new_merges <- false
        for t in terms:
            for rule in rules:
                for s in apply_everywhere(t, rule):
                    if size(s) <= max_size:
                        new_merges <- E.merge(t, s) or new_merges
                        terms <- terms U {s}
        if not new_merges: break
    return E

function EXTRACT(E, t, cost):
    class <- E.get_class(t)
    return argmin_{s in class} cost(s)

function VERIFY(E, terms, denote, envs):
    for t in terms:
        t' <- EXTRACT(E, t, cost)
        for env in envs:
            if denote(t, env) != denote(t', env):
                return VIOLATION
    return SOUND
